    @staticmethod
    def _publish_ids(items) -> list[str]:
        """从批量发布响应的 success/failed 列表提取商品 ID（兼容 str/dict）。"""
        out: list[str] = []
        try:
            rows = list(items or [])
        except TypeError:
            return out
        for item in rows:
            if isinstance(item, dict):
                key = item.get("id") or item.get("productId") or item.get("product_id")
            else:
                key = item
            key = str(key or "").strip()
            if key and key not in out:
                out.append(key)
        return out

    def _publish_one(self, pid: str, on_done=None):
        """单独发布 / 重试一个商品。"""
        if self._is_tiktok():
            # SMT 写操作：TikTok 平台禁止走速卖通发布队列。
            self._log(f"TikTok 平台禁止速卖通发布操作：{pid}（请用「TikTok 刊登」页）",
                      "WARN")
            try:
                self.toast("TikTok 平台不允许速卖通发布操作", False)
            except Exception:
                pass
            if on_done:
                try:
                    on_done()
                except Exception:
                    pass
            return
        if self._is_amazon():
            # SMT 写操作：Amazon 平台禁止走速卖通发布队列。
            self._log(f"Amazon 平台禁止速卖通发布操作：{pid}（请用「Amazon 刊登」页）",
                      "WARN")
            try:
                self.toast("Amazon 平台不允许速卖通发布操作", False)
            except Exception:
                pass
            if on_done:
                try:
                    on_done()
                except Exception:
                    pass
            return

        def go():
            ok = False
            bad = ""
            err = ""
            try:
                from ..integrations.dianxiaomi import DianxiaomiClient as _DXC
                c = _DXC(self._cookies(), overrides=self.cfg.endpoint_overrides or {})
                r = c.batch_publish([str(pid)])
                ok = bool(r.get("success"))
                bad = (r.get("failed") or [{}])[0].get("msg", "") if not ok else ""
            except Exception as ex:  # noqa: BLE001
                err = str(ex)[:100]
            # 结果已确定 → 只计一次（成功/失败都算，重试时同产品只保留最终结果）
            try:
                self._record_publish_result(self.active_platform.id, str(pid), ok)
            except Exception:
                pass
            if err:
                self._log(f"✗ 发布失败：{pid} {err}", "ERROR")
                self.toast(f"发布失败：{err[:60]}", False)
            else:
                self._log(("✓ 发布成功：" if ok else "✗ 发布失败：") + f"{pid} {bad}"[:120],
                          "INFO" if ok else "WARN")
                self.toast(("已提交发布：" if ok else f"发布失败：{bad[:60]}") + str(pid), ok)
            if on_done:
                try:
                    on_done()
                except Exception:
                    pass
        threading.Thread(target=go, daemon=True).start()

